{"query":"query AiringRadar($page: Int!, $start: Int!, $end: Int!) {
  Page(page: $page, perPage: 50) {
    pageInfo { hasNextPage }
    airingSchedules(airingAt_greater: $start, airingAt_lesser: $end, sort: [TIME, ID]) {
      id episode airingAt
      media { id title { romaji english native } format coverImage { large } }
    }
  }
}","variables":{"page":1,"start":1792342799,"end":1792947600}}

